-- GENERATED by `wfi generate` from data/quest/quest-0097.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [97236] = { nil, "Consegna il Fang of Githyiss a qualcuno interessato allo studio dei ragni, ad Aldrassil.", "Un esemplare fresco di una bestia di queste dimensioni è una bella scoperta. Forse qualcuno ad Aldrassil che conosce lo studio dei ragni sarebbe interessato alla zanna.", nil, "Oh, oh. Quanto adoro le sorprese, {name}.\n\nQuesto esemplare aiuterà di sicuro i miei studi.", nil, 0xe6a4e5ad, 0x9adc9237, nil, 0xd5fbb580, "m..m." },
  [97243] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97244] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97245] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97257] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [97899] = { "Campeggio 101: Alchemy", nil, "Quindi hai scelto di preparare intrugli e pozioni come alchimista. Sono sicuro che ti tornerà utile nei tuoi viaggi.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e gli incantatori accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
  [97900] = { "Campeggio 101: Blacksmithing", nil, "Quindi sei <diventato/diventata> fabbro. Ottima scelta, se vuoi essere <sicuro/sicura> che le tue lame non perdano mai il filo.\n\nCredo di conoscere qualcuno che può aiutarti insegnandoti a creare una Sharpening Wheel. Portane una al tuo accampamento e tutti i guerrieri e i ladri della zona faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, nil, 0x469a706e, nil, nil, ".m.mm" },
  [97901] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [97903] = { "Campeggio 101: First Aid", nil, "Quindi ti sei <dedicato/dedicata> al First Aid? Una scelta onorevole... e pragmatica per un {class}.\n\nCredo di conoscere qualcuno che può insegnarti a creare un First Aid Kit per il tuo accampamento. Le ferite sono una realtà nel mondo dell'avventura, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi creare il tuo First Aid Kit. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x6e7c255b, nil, 0x32ff3188, nil, 0x3a282524, ".m.m." },
  [97905] = { "Campeggio 101: Herbalism", nil, "Mi sembra che tu abbia acquisito una certa abilità in erboristeria. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e incantatori, e un Incense Candle può dare una spinta che chi usa la magia apprezzerà di sicuro.", nil, nil, 0xd7cde71c, nil, 0xe0048777, nil, nil, ".m.mm" },
  [97906] = { "Campeggio 101: Leatherworking", nil, "Hai imparato la conciatura. Buon per te, {class}. Credo di conoscere qualcuno che può insegnarti a farti una tenda che ti terrà al fresco nei giorni caldi e all'asciutto nei giorni di pioggia.\n\nCon una buona tenda sopra la testa, ti assicurerai tutto il riposo necessario per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, nil, 0x86e620e9, nil, nil, ".m.mm" },
  [97908] = { "Campeggio 101: Skinning", nil, "Saper ricavare con abilità pelli e cuoio dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nCredo di conoscere qualcuno che può insegnarti a creare una Camp Chair per il tuo accampamento. A volte è importante semplicemente riposarsi, e puoi usare un po' delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a essere al massimo della forma e a colpire dove conta la prossima volta che ti troverai in una zuffa.", nil, "Ecco fatto: ora puoi creare il tuo Camp Chair. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo alla città, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire l'accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, forse dovresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x14236b38, nil, 0x1755b1ba, nil, 0x98c24a76, ".m.m." },
  [97915] = { "Campeggio 101: Alchemy", nil, "Quindi hai scelto di preparare intrugli e pozioni come alchimista. Sono sicuro che ti tornerà utile nei tuoi viaggi.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Mana Well per il tuo accampamento. Costruiscine uno e tutti i guaritori e gli incantatori accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, nil, 0xf6c52c29, nil, nil, ".m.mm" },
